#!/usr/bin/env bash
set -euo pipefail
source "${DOT_ROOT:?}/lib/dot.sh"

# A generated shim, not a symlink: through a symlink BASH_SOURCE would point at
# ~/.local/bin and bin/dot would look for lib/ there.
bin_dir="$HOME/.local/bin"
target="$bin_dir/dot"

shim=$(
  cat <<EOF
#!/usr/bin/env bash
# Generated by core/apply.sh. Points at the repo you installed from.
export DOT_ROOT="$DOT_ROOT"
exec "\$DOT_ROOT/bin/dot" "\$@"
EOF
)

if [[ -x $target && $(<"$target") == "$shim" ]]; then
  ok dot 'shim current'
else
  info write "${target/#$HOME/\~}"
  if [[ $DOT_DRY_RUN != 1 ]]; then
    mkdir -p "$bin_dir"
    printf '%s\n' "$shim" >"$target"
    chmod +x "$target"
  fi
fi

if [[ $DOT_DRY_RUN != 1 ]]; then
  mkdir -p "$DOT_CONFIG_HOME" "$DOT_STATE_HOME" "$HOME/.local/share"
fi
